import { WorkspaceFooter } from "@/components/workspace-footer";
import { PremiumUpgradeProvider } from "@/components/premium-upgrade-provider";
import { localizedPrice } from "@/lib/localized-price";
import { SendingStatusProvider } from "@/components/sending-status";
import { readSendingActive } from "@/lib/sending-status";
import { readRoleUsage } from "@/lib/role-store";
import { readEntitlements } from "@/lib/entitlements";
import { ActivityMarker } from "@/components/activity-marker";
import { Suspense } from "react";
import { requireUser } from "@/lib/session";
import { signOut } from "@/auth";
import { Wordmark } from "@/components/common";
import { WorkspaceBanners } from "@/components/workspace-banners";
import { Navigation } from "@/components/navigation";
import { AccountMenu } from "@/components/account-menu";
import { AppearanceControl } from "@/components/appearance-control";
import { PageTransition } from "@/components/page-transition";
import { WorkspaceLoading } from "@/components/workspace-loading";
import { NotificationProvider } from "@/components/notifications";
import { WorkspaceQuotaProvider } from "@/components/workspace-quota";
import { GmailStatus } from "@/components/gmail-status";
import { readQuotaSnapshot } from "@/lib/quota-usage";
import { HelpTutorial } from "@/components/help-tutorial";
export const dynamic = "force-dynamic";
export const metadata = { robots: { index: false, follow: false } };
async function AuthenticatedLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const user = await requireUser();
  const [quota, entitlements, roleUsage, sending, premiumPrice] =
    await Promise.all([
      readQuotaSnapshot(user.id),
      readEntitlements(user.id),
      readRoleUsage(user.id),
      readSendingActive(user.id),
      localizedPrice(Promise.resolve({})),
    ]);
  return (
    <SendingStatusProvider initialSending={sending}>
      <NotificationProvider>
        <ActivityMarker />
        <WorkspaceQuotaProvider
          quota={quota}
          entitlements={entitlements}
          roleUsage={roleUsage}
        >
          <PremiumUpgradeProvider premiumPrice={premiumPrice}>
            <header>
              <div className="page-container flex flex-wrap items-center justify-between gap-3 pt-[18px]">
                <div className="workspace-header-brand flex items-center gap-4 min-w-0 max-w-full [@media(width_<_640px)]:gap-3">
                  <Wordmark className="shrink-0" />
                </div>
                <div className="workspace-header-controls [font-family:var(--font-sans)] ml-auto flex flex-wrap items-center justify-end gap-3 min-w-0 max-w-full [@media(max-width:_480px)]:flex-wrap [@media(max-width:_480px)]:gap-2">
                  <GmailStatus
                    paused={Boolean(entitlements.gmailPause)}
                    connected={
                      user.gmailAuthorized && !!user.encryptedRefreshToken
                    }
                  />
                  <AppearanceControl />
                  <AccountMenu
                    name={user.name}
                    email={user.email}
                    signOut={async () => {
                      "use server";
                      await requireUser();
                      await signOut({ redirectTo: "/" });
                    }}
                  />
                </div>
                <div className="w-full pt-1 pb-0">
                  <Navigation />
                </div>
              </div>
            </header>
            <main
              id="main-content"
              tabIndex={-1}
              className="page-container pt-[26px] pb-[60px]"
            >
              <WorkspaceBanners />
              <PageTransition>{children}</PageTransition>
            </main>
            <WorkspaceFooter />
            <HelpTutorial />
          </PremiumUpgradeProvider>
        </WorkspaceQuotaProvider>
      </NotificationProvider>
    </SendingStatusProvider>
  );
}

export default function AppLayout({ children }: { children: React.ReactNode }) {
  return (
    <Suspense fallback={<WorkspaceLoading shell />}>
      <AuthenticatedLayout>{children}</AuthenticatedLayout>
    </Suspense>
  );
}
